import{_ as e,c as t,o as a,a2 as s}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"Events & Listeners","description":"","frontmatter":{"sidebarPos":1,"sidebarTitle":"Overview","sidebarGroupTitle":"Events & Listeners"},"headers":[],"relativePath":"system-reference/backend/events/overview.md","filePath":"system-reference/backend/events/overview.md","lastUpdated":1778363927000}'),d={name:"system-reference/backend/events/overview.md"},n=s(`<h1 id="events-listeners" tabindex="-1">Events &amp; Listeners <a class="header-anchor" href="#events-listeners" aria-label="Permalink to &quot;Events &amp; Listeners&quot;">​</a></h1><p>Modularous ships a set of events that fire at key points in the application lifecycle. Listeners react to those events and, when mail is enabled, automatically resolve and dispatch the matching notification class.</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table><thead><tr><th>Class</th><th>Namespace</th><th>Fired When</th></tr></thead><tbody><tr><td><a href="./model-event">ModelEvent</a></td><td><code>Unusualify\\Modularous\\Events</code></td><td>Abstract base — extended by all model-level events</td></tr><tr><td><a href="./user-events#modularoususerregistering">ModularousUserRegistering</a></td><td><code>Unusualify\\Modularous\\Events</code></td><td>Just before a new user is persisted</td></tr><tr><td><a href="./user-events#modularoususerregistered">ModularousUserRegistered</a></td><td><code>Unusualify\\Modularous\\Events</code></td><td>Immediately after a user is created</td></tr><tr><td><a href="./user-events#modularoususerverification">ModularousUserVerification</a></td><td><code>Unusualify\\Modularous\\Events</code></td><td>When an email-verification request is initiated</td></tr><tr><td><a href="./user-events#verifiedemailregister">VerifiedEmailRegister</a></td><td><code>Unusualify\\Modularous\\Events</code></td><td>When a user completes registration via verified e-mail</td></tr></tbody></table><h2 id="listeners" tabindex="-1">Listeners <a class="header-anchor" href="#listeners" aria-label="Permalink to &quot;Listeners&quot;">​</a></h2><table><thead><tr><th>Class</th><th>Namespace</th><th>Listens To</th></tr></thead><tbody><tr><td><a href="./listener">Listener</a></td><td><code>Unusualify\\Modularous\\Listeners</code></td><td>Abstract base — extended by concrete listeners</td></tr></tbody></table><h2 id="event-traits" tabindex="-1">Event Traits <a class="header-anchor" href="#event-traits" aria-label="Permalink to &quot;Event Traits&quot;">​</a></h2><p>All <code>ModelEvent</code> subclasses automatically gain the following traits:</p><table><thead><tr><th>Trait</th><th>What it captures</th></tr></thead><tbody><tr><td><code>EventChanges</code></td><td>Changed model attributes and relationships</td></tr><tr><td><code>EventStateable</code></td><td>Previous / current stateable state</td></tr><tr><td><code>EventUrls</code></td><td>Current and previous HTTP request URLs</td></tr><tr><td><code>EventUser</code></td><td>Authenticated user at the time the event fired</td></tr></tbody></table><h2 id="systemnotification-module-events" tabindex="-1">SystemNotification Module Events <a class="header-anchor" href="#systemnotification-module-events" aria-label="Permalink to &quot;SystemNotification Module Events&quot;">​</a></h2><p>The <code>SystemNotification</code> module (in <code>Modules\\SystemNotification\\Events\\</code>) defines a second set of domain events that fire on model lifecycle changes. These extend <code>ModelEvent</code> and are wired to their own listeners and notification classes:</p><table><thead><tr><th>Event</th><th>Fired When</th></tr></thead><tbody><tr><td><code>ModelCreated</code></td><td>Any model is created</td></tr><tr><td><code>ModelUpdated</code></td><td>Any model is updated</td></tr><tr><td><code>ModelDeleted</code></td><td>A model is soft-deleted</td></tr><tr><td><code>ModelRestored</code></td><td>A soft-deleted model is restored</td></tr><tr><td><code>ModelForceDeleted</code></td><td>A model is permanently deleted</td></tr><tr><td><code>StateableUpdated</code></td><td>A model transitions state via <code>HasStateable</code></td></tr><tr><td><code>AssignmentCreated</code></td><td>A new <code>Assignment</code> is created</td></tr><tr><td><code>AssignmentUpdated</code></td><td>An existing <code>Assignment</code> is updated</td></tr><tr><td><code>PaymentCompleted</code></td><td>A payment completes</td></tr><tr><td><code>PaymentFailed</code></td><td>A payment fails</td></tr><tr><td><code>UnreadChatMessage</code></td><td>Unread chat messages exist for a <code>Chatable</code> model</td></tr></tbody></table><p>All these extend <code>ModelEvent</code>, so they automatically carry <code>EventUser</code>, <code>EventUrls</code>, <code>EventChanges</code>, and <code>EventStateable</code> context.</p><p>→ <a href="/system-reference/backend/notifications/system-notifications">System Notifications — event/listener/notification map</a></p><hr><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Action: model saved / user registers]</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  Event dispatched</span></span>
<span class="line"><span>  (ModelEvent subclass or user event)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  Laravel event system</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─► Listener::handle($event)</span></span>
<span class="line"><span>        │       └─ resolves {EventName}Notification</span></span>
<span class="line"><span>        │          sends mail if modularous.mail.enabled = true</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └─► Broadcasting (ModelEvent only)</span></span>
<span class="line"><span>                broadcast on private channel: models.{model_id}</span></span>
<span class="line"><span>                broadcast on public channel:  model</span></span>
<span class="line"><span>                event name: modularous.{event_name}</span></span></code></pre></div><p>→ <a href="/guide/broadcasting/overview">Broadcasting guide</a></p>`,18),o=[n];function r(i,l,c,p,h,u){return a(),t("div",null,o)}const f=e(d,[["render",r]]);export{m as __pageData,f as default};
